{"implementation":"def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    num_attempts = len(attempts)
    success_indices = [i for i, a in enumerate(attempts) if a['success']]
    if success_indices:
        decision = 'completed'
        memory_append = None
        next_attempt = num_attempts
    else:
        last = attempts[-1]
        memory_append = {'reflection': last['reflection'], 'signature': last['failure_signature']}
        if num_attempts < max_attempts:
            decision = 'retry'
            next_attempt = num_attempts + 1
        else:
            decision = 'failed'
            next_attempt = num_attempts
    return {
        'decision': decision,
        'memory_append': memory_append,
        'next_attempt': next_attempt
    }"}
